/** 与 src/config.ts BOT_SENDERS 对齐：机器人转发不当真人喊单 */
const BOT_SENDERS = new Set(["人工智能机器人", "人工智能和机器人", "phanes"]);
const BOT_TELEGRAM_HANDLES = new Set(["rick"]);
const isBotSender = (name, group) => {
  if (!name) return false;
  const n = String(name).trim();
  const handle = n.replace(/^@/, "").toLowerCase();
  return BOT_SENDERS.has(n.toLowerCase()) || /人工智能\s*和?\s*机器人/.test(n) || ((n.startsWith("@") || /^tg:/i.test(String(group || ""))) && BOT_TELEGRAM_HANDLES.has(handle)) || (/^tg:/i.test(String(group || "")) && /^@[a-z0-9_]+bot$/i.test(n));
};
