const precisionLabel = (precision) => ({ second: "秒级", minute: "分钟级（仅秒级内有效）", "minute-after": "不作首喊基准", "hour-after": "不作首喊基准", "day-after": "不作首喊基准", "minute-prior": "前一分钟收盘≈（最多 2 分钟，近似）", request: "请求时刻（喊单前≤2秒）", bucket: "不作首喊基准", unknown: "未知" })[precision] || "未知";
