  source: (c) => `${c.baseMcSource || ""}/${c.baseMcBasis || ""}`, precision: (c) => c.pricePrecision || "unknown",
  baseMc: (c) => c.baseMc, athMc: (c) => c.athMc, nowMc: (c) => c.nowMc, nowX: (c) => c.nowX, peakX: (c) => c.peakX,
  peakX24: (c) => c.peakX24, peakAt: (c) => c.peakAt, endX24: (c) => c.endX24, drawdownPct24: (c) => c.drawdownPct24,
  coveragePct24: (c) => c.coveragePct24, eligible: (c) => c.performanceEligible ? 1 : 0,
  pnl: (c) => c.nowX == null ? null : c.nowX - 1, status: (c) => OUTCOME_ORDER[outcome(c)[0]],
  peakGain: (c) => c.peakX == null ? null : c.peakX - 1, calls: (c) => c.calls ?? 1,
  // 喊单人 stats 行
  winRate: (r) => r.winRate, medianPeakX: (r) => r.medianPeakX, avgPeakX: (r) => r.avgPeakX,
  best: (r) => r.best?.x ?? null,
